<?php
 namespace Pterodactyl\Services\Dezerx; use Throwable; use Illuminate\Support\Str; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; class Brand {  public const FALLBACK = 'kts-host'; private const HISTORY_KEY = 'brand-files'; private const MAX_LENGTH = 32; private static ?string $slug = null; public static function name(): string { try { $logo = Appearance::logo(); $name = $logo['mode'] === 'image' ? ($logo['alt'] ?: $logo['text']) : ($logo['text'] ?: $logo['alt']); } catch (Throwable) { $name = ''; } return trim((string) $name) ?: trim((string) config('app.name', '')) ?: self::FALLBACK; } public static function slug(): string { if (self::$slug !== null) { return self::$slug; } $slug = trim(Str::limit(Str::slug(self::name()), self::MAX_LENGTH, ''), '-'); $slug = preg_match('/^[a-z0-9][a-z0-9-]*$/', $slug) === 1 ? $slug : self::FALLBACK; self::remember($slug); return self::$slug = $slug; } public static function file(string $suffix): string { return '.' . self::slug() . '-' . $suffix; } public static function files(string $suffix): array { return array_map(fn (string $slug) => '.' . $slug . '-' . $suffix, self::slugs()); } public static function oldFiles(string $suffix): array { return array_slice(self::files($suffix), 1); } public static function read(ServerFiles $files, string $directory, string $suffix, ?int $maxBytes = null): ?string { $directory = '/' . trim($directory, '/'); foreach (self::files($suffix) as $index => $name) { $contents = $files->fileContents(rtrim($directory, '/') . '/' . $name, $maxBytes); if ($contents !== null) { if ($index > 0) { $files->renamePath($directory, $name, self::file($suffix)); } return $contents; } } return null; } public static function write(ServerFiles $files, string $directory, string $suffix, string $contents): bool { $directory = '/' . trim($directory, '/'); if (!$files->writeFile(rtrim($directory, '/') . '/' . self::file($suffix), $contents)) { return false; } if (($old = self::oldFiles($suffix)) !== []) { $files->deletePaths($directory, $old); } return true; } public static function slugs(): array { $current = self::slug(); $history = (array) (Settings::get(self::HISTORY_KEY)['used'] ?? []); return array_values(array_unique([$current, ...array_filter($history, 'is_string'), self::FALLBACK])); } private static function remember(string $slug): void { try { $used = array_values(array_filter((array) (Settings::get(self::HISTORY_KEY)['used'] ?? []), 'is_string')); if (($used[0] ?? null) !== $slug) { Settings::put(self::HISTORY_KEY, ['used' => array_slice(array_values(array_unique([$slug, ...$used])), 0, 20)]); } } catch (Throwable) { } } }